$('callList').onclick=ev=>{const b=ev.target.closest('[data-call]');if(b){selectIncident(Number(b.dataset.call));}};$('respond').onclick=respond;$('return').onclick=()=>{returnEngine(selected());renderUI();};$('move').onclick=()=>{moveMode=!moveMode;renderUI();};$('extinguish').onclick=()=>{selected().workActive=true;log('FPT — lance établie. Extinction en cours.',true);renderUI();};$('pause').onclick=()=>{if(state.ended){endShift();return;}state.paused=!state.paused;renderUI();};$('speed').onchange=ev=>state.speed=Number(ev.target.value);$('density').oninput=ev=>{setDensity(state,Number(ev.target.value));$('densityValue').textContent=state.density;};
$('follow').onclick=()=>{setGarage(false);follow=!follow;$('follow').classList.toggle('active',follow);};$('night').onclick=()=>{nightOverride=!lastNight;};renderer.domElement.addEventListener('pointermove',ev=>{if(down&&down.button===0&&Math.hypot(ev.clientX-down.x,ev.clientY-down.y)>6){follow=false;$('follow').classList.remove('active');}});$('collapseCalls').onclick=()=>{document.querySelector('.dispatch').classList.toggle('collapsed');$('collapseCalls').textContent=document.querySelector('.dispatch').classList.contains('collapsed')?'+':'−';};$('journalToggle').onclick=()=>$('journal').classList.toggle('hidden');$('closeJournal').onclick=()=>$('journal').classList.add('hidden');
let reinforcementsOpen=false;function showReinforcements(){reinforcementsOpen=true;modal(volunteerPanel(state));$('modalContent').querySelectorAll('[data-recall-level]').forEach(b=>b.onclick=()=>{const level=Number(b.dataset.recallLevel),n=requestVolunteers(state,level);sound('selective');log(`${level===1?'Rappel astreinte':'Appel général'} : ${n} SPV en route.`,true);showReinforcements();});$('recallStatus').onclick=ev=>{const b=ev.target.closest('[data-cancel-recall]');if(b){cancelVolunteer(state,Number(b.dataset.cancelRecall));showReinforcements();}};}
