$('audio').onclick=()=>{modal(`<span class="eyebrow">ALERTE DU CENTRE</span><h2>Sons et radio</h2><p>Le sélectif utilise votre enregistrement. Les deux-tons utilisent également votre enregistrement. Sur route, ils s’activent aux intersections et à l’approche de la circulation. Le volume diminue avec votre éloignement.</p><label for="volume">Volume sonore</label><input id="volume" type="range" min="0" max="1" step=".05" value="${getVolume()}"><div class="actions"><button id="testPager">Bipeur</button><button id="testTwoTone">Deux-tons</button><button id="radioVoice" ${radioVoice.supported?'':'disabled'}>${radioVoice.supported?(radioVoice.isMuted()?'Radio parlée coupée':'Radio parlée active'):'Radio parlée indisponible'}</button><button id="testRadio" ${radioVoice.supported?'':'disabled'}>Essai radio</button><button id="mute">${isSoundOn()?'Couper le son':'Activer le son'}</button><button data-close>Fermer</button></div>`);$('volume').oninput=e=>setVolume(Number(e.target.value));$('testPager').onclick=async()=>{await testPager();$('audio').textContent='Son actif';$('mute').textContent='Couper le son';};$('testTwoTone').onclick=async()=>{await testTwoTone();$('audio').textContent='Son actif';$('mute').textContent='Couper le son';};$('radioVoice').onclick=()=>{radioVoice.setMuted(!radioVoice.isMuted());radioVoice.activate();$('radioVoice').textContent=radioVoice.isMuted()?'Radio parlée coupée':'Radio parlée active';};$('testRadio').onclick=async()=>{if(!isSoundOn())await toggleSound();radioVoice.setMuted(false);radioVoice.activate();radioVoice.enqueue('Radio · CIS : Essai radio. Centre de secours de Valmont, reçu cinq sur cinq.',true,true);$('radioVoice').textContent='Radio parlée active';$('audio').textContent='Son actif';$('mute').textContent='Couper le son';};$('mute').onclick=async()=>{const on=await toggleSound();$('audio').textContent=on?'Son actif':'Son coupé';$('mute').textContent=on?'Couper le son':'Activer le son';};};
$('help').onclick=()=>modal(`<span class="eyebrow">UNE GARDE AU CSP</span><h2>Jouer dans le quartier</h2><p>La garde dure 24 heures, de 08 h à 08 h, avec 5 à 20 interventions. À vitesse normale, 24 heures se déroulent en 24 minutes. Le curseur règle la densité de 5 à 20 interventions par garde.</p><ol><li>Sélectionnez une intervention : la caméra se centre sur les lieux.</li><li>Cliquez sur chaque moyen disponible dans son panneau pour le déclencher immédiatement.</li><li>Suivez les moyens engagés et établissez une lance à leur arrivée sur un feu. Le bouton ⌖ propose des positions facultatives, numérotées sur la carte. Repliez le matériel avant de déplacer un engin déjà installé.</li><li>Un engin disponible sur route peut être réengagé immédiatement. La remise en condition se fait sur site ou au CH.</li><li>Le CCF assure les feux urbains, les feux de végétation et les opérations diverses. Le FPT ne traite pas les feux de végétation.</li><li>Le FPTL est un fourgon compact de 2 000 L pour les feux urbains. Pour la végétation, engagez les CCF.</li><li>Un VTU peut assurer les premiers secours en attendant un VSAV. Il ne remplace pas le transport sanitaire.</li></ol><p>Sur un feu de bâtiment, les commandes ↗ Évacuer et ϟ Gaz / élec. deviennent disponibles après reconnaissance. L’équipe rejoint les lieux, accompagne les occupants ou coupe les énergies, puis revient à l’engin. Les deux opérations se succèdent pour garder un équipage disponible. Après un accident, le dépannage et le nettoyage de la chaussée sont automatiques ; les secours peuvent rentrer pendant que la voirie termine.</p><p>Les automobilistes se rangent pour les secours lorsqu’un bas-côté est libre, puis reprennent leur voie après le convoi.</p><p>A/E font tourner la caméra. Q/Z/S/D ou le glissement déplacent la vue. Clic droit et glissement font pivoter la caméra. La molette zoome. La croix ferme la fiche sans annuler les engagements. Cliquez sur une intervention pour la rouvrir.</p><p>Ville fictive : centre-ville, centre commercial, forêt et lac, immeubles, stade et voie rapide. Deux objectifs par mission : premier moyen opérationnel et fin de prise en charge. Les retards n’arrêtent pas l’intervention. Le son est actif dès votre premier clic. Les soins et les opérations diverses démarrent automatiquement après reconnaissance. Sur un feu, choisissez vos lances et l’alimentation dans la commande de l’engin. Le VLI assiste les victimes graves, le VPL assure le sauvetage nautique avec son bateau. Dans le panneau de l’EPA, l’icône lance déclenche une attaque en hauteur après alimentation d’un fourgon proche sur poteau. L’icône brancard lance l’évacuation par nacelle lorsqu’un bilan signale un escalier trop étroit. Le VSAV prend le relais au sol. Attendez la remise de la victime et le repli avant de repartir.</p><p>Le chef de centre rentre dormir à son domicile vers 22 h avec sa VLCG et rejoint le CIS vers 7 h. Une intervention en cours passe en priorité. Il reste engageable depuis sa maison, après réveil et préparation.</p><div class="actions"><button data-close>Reprendre la garde</button></div>`);
$('dismissSpv').onclick=()=>{const n=dismissCrew(state);log(`${n} SPV disponibles quittent le CIS. Les équipages engagés restent mobilisés.`,true);renderUI();};$('recall').onclick=()=>showReinforcements();$('nextCall').onclick=()=>{requestNextCall(state,()=>sound('call'));renderUI();};
let down=null;renderer.domElement.addEventListener('pointerdown',e=>down={x:e.clientX,y:e.clientY,button:e.button});renderer.domElement.addEventListener('pointerup',ev=>{if(!down||down.button!==0||Math.hypot(ev.clientX-down.x,ev.clientY-down.y)>6)return;pointer.set(ev.clientX/innerWidth*2-1,-ev.clientY/innerHeight*2+1);raycaster.setFromCamera(pointer,camera);if(tacticalOpen){const hit=raycaster.intersectObjects(placementMarkers.root.children.filter(m=>m.visible),true)[0];if(hit){let node=hit.object;while(node&&node.userData.placementIndex==null)node=node.parent;const e=engines.find(e=>e.id===tacticalOpen);if(node&&e)choosePlacement(e,node.userData.placementIndex);return;}}const hit=raycaster.intersectObjects([...engines.map(e=>e.model),...parkedPlayerVehicles(engines.find(e=>e.kind==='VLCG')).map(v=>v.model)],true)[0];if(hit){const cg=engines.find(e=>e.kind==='VLCG'),spare=parkedPlayerVehicles(cg).find(v=>{let n=hit.object;while(n){if(n===v.model)return true;n=n.parent;}return false;});if(spare){incidentPanelOpen=false;choosePlayerVehicle(spare.model.userData.playerVehicle);renderIncident();return;}const e=engines.find(e=>{let n=hit.object;while(n){if(n===e.model)return true;n=n.parent;}return false;});if(e){selectEngine(e);vehiclePanelOpen=true;incidentPanelOpen=false;renderIncident();renderVehiclePanel();return;}}if(moveMode){const p=new T.Vector3();if(raycaster.ray.intersectPlane(ground,p)){const e=selected();if(arm(e)){setRoute(e,[p.x,p.z],'moving');moveMode=false;log(`${e.id} — déplacement vers le point désigné.`,true);renderUI();}}}});
function setGarage(v){if(v)closePlacement();garageView=v;district.roofs.forEach(r=>r.visible=false);$('garage').classList.toggle('active',v);$('garageLabels').classList.add('hidden');$('incidentPanel').classList.toggle('hidden',v||!incidentPanelOpen||!callNow());if(v){follow=false;$('follow').classList.remove('active');controls.target.set(-70,0,86);camera.position.set(-38,65,147);}}
$('garage').onclick=()=>{vehiclePanelOpen=false;incidentPanelOpen=false;renderVehiclePanel();setGarage(true);};
window.addEventListener('keydown',ev=>{if(!['q','z','s','d','a','e'].includes(ev.key.toLowerCase())||ev.ctrlKey||ev.metaKey||ev.altKey||ev.target?.closest?.('input,select,textarea,[contenteditable=true]')||$('modal').open)return;ev.preventDefault();cameraKeys.add(ev.key.toLowerCase());if(['q','z','s','d'].includes(ev.key.toLowerCase())){follow=false;$('follow').classList.remove('active');}});
window.addEventListener('keyup',ev=>cameraKeys.delete(ev.key.toLowerCase()));window.addEventListener('blur',()=>cameraKeys.clear());
function panKeyboard(dt){if(!cameraKeys.size)return;const turn=(cameraKeys.has('a')?1:0)-(cameraKeys.has('e')?1:0);if(turn){const offset=camera.position.clone().sub(controls.target);offset.applyAxisAngle(new T.Vector3(0,1,0),turn*dt);camera.position.copy(controls.target).add(offset);}const direction=camera.getWorldDirection(new T.Vector3());direction.y=0;direction.normalize();const right=new T.Vector3().crossVectors(direction,new T.Vector3(0,1,0)),movement=new T.Vector3();if(cameraKeys.has('z'))movement.add(direction);if(cameraKeys.has('s'))movement.sub(direction);if(cameraKeys.has('d'))movement.add(right);if(cameraKeys.has('q'))movement.sub(right);movement.normalize().multiplyScalar(dt*Math.max(16,camera.position.distanceTo(controls.target)*.55));controls.target.add(movement);camera.position.add(movement);}
if(typeof ResizeObserver!=='undefined'){
 const header=document.querySelector('header'),footer=document.querySelector('.bottom'),dispatch=document.querySelector('.dispatch'),fleet=$('fleetSidebar'),panels=[$('incidentPanel'),$('vehiclePanel')];
 const layout=new ResizeObserver(()=>{
  const head=header.getBoundingClientRect(),dock=footer.getBoundingClientRect(),style=document.documentElement.style;
  const setSize=(key,value)=>{if(style.getPropertyValue(key)!==value)style.setProperty(key,value);};
  setSize('--hud-top',(head.bottom+16)+'px');setSize('--dock-height',dock.height+'px');
  // Frame the unobstructed map; on smaller screens the detail sheet opens on the left.
  let left=12,right=fleet.getBoundingClientRect().left-12,top=head.bottom+16;
  for(const node of [dispatch,...panels]){
   if(node.classList.contains('hidden')||getComputedStyle(node).visibility==='hidden')continue;
   const rect=node.getBoundingClientRect();if(!rect.width||!rect.height)continue;
   if(rect.left<innerWidth*.1)left=Math.max(left,rect.right+12);else right=Math.min(right,rect.left-12);
  }
  const radio=$('radioBanner');if(!radio.hidden)top=Math.max(top,radio.getBoundingClientRect().bottom+12);
  const bottom=dock.top-12;
  if(right-left>80&&bottom-top>80)camera.setViewOffset(innerWidth,innerHeight,innerWidth/2-(left+right)/2,innerHeight/2-(top+bottom)/2,innerWidth,innerHeight);
  else camera.clearViewOffset();
 });
 for(const node of [header,footer,dispatch,fleet,...panels,$('radioBanner')])layout.observe(node);
}
